import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0])
    lines = input_data[1:]

    typedefs = {}

    def normalize_type(type_str):
        stars = 0
        amps = 0
        base_name = ""

        i = 0
        while i < len(type_str):
            if type_str[i] == '*':
                stars += 1
            elif type_str[i] == '&':
                amps += 1
            else:
                break
            i += 1

        base_name = type_str[i:]

        if base_name == "void":
            pass
        elif base_name == "errtype":
            return ("errtype", 0)
        elif base_name in typedefs:
            base_info = typedefs[base_name]
            if base_info[0] == "errtype":
                return ("errtype", 0)
            # base_info is ("void", count)
            base_stars = base_info[1]
            # We need to apply amps and stars to the base
            # First resolve amps on the base
            effective_base_stars = base_stars - amps
            if effective_base_stars < 0:
                return ("errtype", 0)
            # Then add the new stars
            total_stars = effective_base_stars + stars
            return ("void", total_stars)
        else:
            # Undefined type
            return ("errtype", 0)

        # If base is void
        effective_void_stars = stars - amps
        if effective_void_stars < 0:
            return ("errtype", 0)
        return ("void", effective_void_stars)

    output = []

    for line in lines:
        parts = line.split()
        op = parts[0]

        if op == "typedef":
            A = parts[1]
            B = parts[2]

            res_type, res_count = normalize_type(A)
            typedefs[B] = (res_type, res_count)

        elif op == "typeof":
            A = parts[1]
            res_type, res_count = normalize_type(A)

            if res_type == "errtype":
                output.append("errtype")
            else:
                # Format as void followed by res_count asterisks
                result_str = "void" + "*" * res_count
                output.append(result_str)

    for line_out in output:
        print(line_out)

if __name__ == "__main__":
    solve()
